# Вариант В: университет и склад. Формат задачи см. build.py
V = 'C'
TASKS = [
dict(n=1, pts=0.5, title='Вход в общежитие', topics='if / elif / else, not in, or',
 text='В окне уже заданы список `students` и три фразы: `stranger_msg`, `late_msg`, `ok_msg`. Вводятся имя и час возвращения (целое число от 0 до 23).\n\nЕсли имени нет в списке студентов, напечатайте `stranger_msg`. Если студент в списке и вернулся в 23 часа или позже, либо раньше 6 утра, напечатайте `late_msg`. Во всех остальных случаях напечатайте `ok_msg`.',
 fin='Первая строка — имя, вторая — час (целое число).', fout='Одна из трёх фраз.',
 pre="students = ['Аня', 'Борис', 'Вера']\nstranger_msg = 'Посторонним вход запрещён'\nlate_msg = 'Запишем в журнал опозданий'\nok_msg = 'Проходите'",
 inputs=[['Аня','22'],['Борис','23'],['Глеб','12'],['Вера','5'],['Аня','6'],['Борис','0']],
 sol="name = input()\nhour = int(input())\n\nif name not in students:\n    print(stranger_msg)\nelif hour >= 23 or hour < 6:\n    print(late_msg)\nelse:\n    print(ok_msg)\n",
 hint='Сначала отсеките посторонних (`not in`), потом проверьте час через `or`, остальное — `else`. Час — строка, нужен `int`.',
 idea='Три исхода — цепочка `if / elif / else`: нет в списке; поздно или слишком рано; нормальное время.',
 steps=['`name = input()` читает имя, `hour = int(input())` читает час и сразу делает его числом.','`name not in students` — первая проверка: если человека нет, час не важен.','`hour >= 23 or hour < 6` — поздно, если верно **хотя бы одно** из двух условий.','`else` — можно проходить.'],
 mist=['Написали `hour >= 23 and hour < 6`: оба условия сразу не бывают верны, опоздавших не будет.','Забыли `int(...)`: сравнение строки с числом — ошибка `TypeError`.','Границы: 23 — уже поздно, 6 — ещё можно; перепутали `>=` и `>`.']),
dict(n=2, pts=1, title='Сданные предметы', topics='while True, break, split, список',
 text='Вводятся строки вида `предмет:балл` (балл — целое число), пока не будет введено слово `END`.\n\nНапечатайте список предметов, по которым балл **не ниже 60**, в порядке ввода. Если таких нет, напечатайте пустой список.',
 fin='Строки `предмет:балл`, последняя строка — `END`.', fout='Список предметов в квадратных скобках, как печатает `print(список)`.',
 pre='',
 inputs=[['Python:85','Статистика:59','Английский:60','END'],['END'],['Матан:40','Физика:30','END'],['История:100','Право:75','END'],['Химия:60','END']],
 sol="passed = []\n\nwhile True:\n    line = input()\n    if line == 'END':\n        break\n    subject, mark = line.split(':')\n    if int(mark) >= 60:\n        passed.append(subject)\n\nprint(passed)\n",
 hint='Список создайте до цикла. Строку режьте по двоеточию: `subject, mark = line.split(":")`. Балл — строка, нужен `int`. «Не ниже» — это `>=`.',
 idea='Читаем строки в бесконечном цикле, на слове `END` выходим через `break`, остальное разбираем и фильтруем.',
 steps=['`passed = []` создаём **до** цикла, иначе список обнулялся бы на каждой строке.','`while True:` — читаем, пока сами не прервём цикл.','`line == "END"` → `break`: выходим, не обрабатывая слово `END`.','`subject, mark = line.split(":")` — две части строки в две переменные.','`int(mark) >= 60` — «не ниже» включает ровно 60.'],
 mist=['Список создан внутри цикла — в конце останется только последний предмет.','Не сделали `int(mark)`: сравнение строки с числом — ошибка `TypeError`.','Поставили `>`: предмет ровно с 60 баллами пропадёт.']),
dict(n=3, pts=0.5, title='Выдача со склада', topics='split(", "), in, remove',
 text='В первой строке товары на складе через «запятая + пробел». Во второй — название товара, который нужно выдать.\n\nЕсли он есть на складе, удалите его из списка и напечатайте список. Если его нет — напечатайте `Нет на складе`.',
 fin='Первая строка — товары через `, `. Вторая — одно название.', fout='Список товаров в квадратных скобках или фраза `Нет на складе`.',
 pre='',
 inputs=[['мышь, клавиатура, монитор','клавиатура'],['мышь, монитор','кабель'],['лампа','лампа'],['стол, стул','Стол'],['ручка, блокнот, папка','папка']],
 sol="goods = input().split(', ')\nname = input()\n\nif name in goods:\n    goods.remove(name)\n    print(goods)\nelse:\n    print('Нет на складе')\n",
 hint='Строку разбейте `split(", ")`. Если товар есть (`in`) — `remove` и печать списка, иначе печатаем фразу.',
 idea='Превращаем строку в список и по наличию товара выбираем: удалить и показать остаток или сообщить, что товара нет.',
 steps=['`input().split(", ")` — строка превращается в список товаров.','`name in goods` — истина, если товар есть.','`goods.remove(name)` удаляет товар и меняет сам список.','Фраза `Нет на складе` печатается только в `else`.'],
 mist=['`remove` для товара, которого нет, даёт `ValueError` — поэтому сначала `in`.','Результат `remove` присвоили переменной: получится `None`.','Регистр важен: `Стол` и `стол` — разные названия.']),
dict(n=4, pts=1, title='Что пора заказать', topics='два списка, range(len())',
 text='В первой строке названия товаров через пробел, во второй — остатки на складе (целые числа) в том же порядке. В третьей — минимальный запас.\n\nНапечатайте названия товаров, остаток которых **меньше** минимального запаса (строго), каждое с новой строки.',
 fin='Три строки: названия, остатки, минимальный запас.', fout='Названия по одному на строке или пустой вывод.',
 pre='',
 inputs=[['мышь кабель стол лампа','5 50 2 10','10'],['А Б','100 200','50'],['Один','9','10'],['Х У Ф','10 5 20','10'],['Папка Ручка','1 0','5']],
 sol="goods = input().split()\nleft = input().split()\nmin_count = int(input())\n\nfor i in range(len(goods)):\n    if int(left[i]) < min_count:\n        print(goods[i])\n",
 hint='Названия и остатки лежат в двух списках, связь — одинаковый номер. Переберите номера через `range(len(...))`. Остатки — строки, нужен `int`.',
 idea='Идём по номерам: по номеру берём и товар, и остаток, сравниваем остаток с минимальным запасом.',
 steps=['`goods` и `left` — списки **строк**; остаток берём как `int(left[i])`.','`range(len(goods))` — номера 0, 1, 2, …','`int(left[i]) < min_count` — «меньше», то есть `<`.','Печатаем `goods[i]` — товар с тем же номером.'],
 mist=['`<=` вместо `<`: товар с остатком ровно как запас попадёт зря.','Сравнили `left[i] < min_count` без `int`: строка с числом — ошибка `TypeError`.','Напечатали `left[i]` вместо `goods[i]`.']),
dict(n=5, pts=0.75, title='Общие студенты', topics='множества, пересечение',
 text='Две строки: имена студентов группы по Python и группы по статистике (через пробел).\n\nНапечатайте, сколько студентов учится **в обеих** группах.',
 fin='Две строки, имена через пробел.', fout='Одно число.',
 pre='',
 inputs=[['Аня Борис Вера','Вера Глеб Аня'],['Омск','Омск'],['А Б В','Г Д'],['Зоя','Зоя Ира Лев'],['Паша Рита','Сергей Тоня']],
 sol="python = set(input().split())\nstatistics = set(input().split())\n\nprint(len(python & statistics))\n",
 hint='Превратите обе строки во множества. «В обеих группах» — пересечение `&`.',
 idea='Пересечение двух множеств хранит тех, кто есть и в первом, и во втором.',
 steps=['`set(input().split())` — строка → список → множество.','`python & statistics` — студенты обеих групп.','`len(...)` — сколько их.'],
 mist=['`|` вместо `&`: посчитаются все студенты хотя бы одной группы.','Сложили `len(python) + len(statistics)`: общий студент посчитается дважды.','`print(python & statistics)` печатает множество, а нужно число.']),
dict(n=6, pts=1.25, title='Только Python и статистика', topics='множества, пересечение и разность',
 text='Три строки с названиями курсов через запятую **без пробела**, которые посещает студент: Аня; Борис; Вера. Названия бывают из нескольких слов.\n\nНапечатайте, сколько курсов посещает **и Аня, и Борис, но не Вера**.',
 fin='Три строки, курсы через запятую.', fout='Одно число.',
 pre='',
 inputs=[['Python,Статистика,Английский','Python,Английский','Статистика'],['Основы ИИ,Python','Основы ИИ','Python'],['Х','Х','Х'],['Право,Экономика','Право,Экономика,История','Экономика'],['Матан','Физика','Матан']],
 sol="anna = set(input().split(','))\nboris = set(input().split(','))\nvera = set(input().split(','))\n\nboth = anna & boris\nprint(len(both - vera))\n",
 hint='Сначала пересеките курсы Ани и Бориса `&`, потом вычтите `-` курсы Веры.',
 idea='Находим общие курсы Ани и Бориса (пересечение) и убираем те, которые посещает Вера (разность).',
 steps=['Разделитель — запятая без пробела: `.split(",")`. Без аргумента названия с пробелами разорвутся.','`anna & boris` — курсы, которые посещают оба.','`both - vera` — из них те, которых нет у Веры.','`len(...)` — сколько их.'],
 mist=['`split()` вместо `split(",")`: «Основы ИИ» разорвётся на два курса.','Вычли в другую сторону `vera - both`: получится совсем другое множество.','`|` вместо `&` в первом шаге: получатся курсы хотя бы одного из двоих.']),
dict(n=7, pts=0.75, title='Студенты группы', topics='словарь, перебор ключей',
 text='В окне задан словарь `groups`: студент → название группы. Вводится название группы.\n\nНапечатайте студентов этой группы, каждого с новой строки, в порядке словаря. Если таких нет, ничего не печатайте.',
 fin='Одна строка — название группы.', fout='Имена по одному на строке или пустой вывод.',
 pre="groups = {'Анна': 'БИ-1', 'Борис': 'БИ-2', 'Вера': 'БИ-1', 'Глеб': 'ЭК-1', 'Дарья': 'БИ-2', 'Егор': 'БИ-1'}",
 inputs=[['БИ-1'],['БИ-2'],['ЭК-1'],['ЮР-1'],['би-1']],
 sol="group = input()\n\nfor student in groups:\n    if groups[student] == group:\n        print(student)\n",
 hint='Цикл `for student in groups` перебирает **ключи** (студентов). Группа берётся как `groups[student]`.',
 idea='Идём по студентам и печатаем тех, у кого группа совпадает с введённой.',
 steps=['`for student in groups:` — переменная `student` по очереди получает каждого студента.','`groups[student]` — группа этого студента.','`== group` — совпадение с введённым названием.','Печатаем `student`, а не группу.'],
 mist=['Напечатали `groups[student]`: получится название группы вместо имени.','Ждали, что цикл даст значения: он перебирает ключи.','Регистр важен: `би-1` не равно `БИ-1`.']),
dict(n=8, pts=1.25, title='Предметы с хорошей средней', topics='словарь списков, sum / len',
 text='В окне задан словарь `subjects`: предмет → список оценок группы за семестр. Вводится порог.\n\nНапечатайте предметы, у которых **средняя** оценка **не ниже** порога, каждый с новой строки, в порядке словаря.',
 fin='Одна строка — порог (целое число).', fout='Названия предметов по одному на строке или пустой вывод.',
 pre="subjects = {'Python': [5, 4, 5, 4], 'Статистика': [3, 4, 3, 4], 'Английский': [5, 5, 5, 4], 'Право': [3, 3, 4, 3]}",
 inputs=[['4'],['5'],['3'],['2'],['6']],
 sol="limit = int(input())\n\nfor subject in subjects:\n    average = sum(subjects[subject]) / len(subjects[subject])\n    if average >= limit:\n        print(subject)\n",
 hint='Среднее — это `sum(список) / len(список)`. Посчитайте его для каждого предмета и сравните с порогом. «Не ниже» — `>=`.',
 idea='Для каждого ключа берём список, делим сумму на длину и сравниваем среднее с порогом.',
 steps=['`subjects[subject]` — список оценок предмета.','`sum(...)` — сумма, `len(...)` — количество оценок; `/` даёт среднее.','`average >= limit` — не ниже порога.','Печатаем `subject`, а не среднее.'],
 mist=['Забыли разделить на `len(...)`: сравнится сумма, а не среднее.','Использовали `//` вместо `/`: среднее округлится вниз, и граница сдвинется.','`>` вместо `>=`: предмет со средним ровно как порог пропадёт.'],
 trace='Python: 5 + 4 + 5 + 4 = 18, делим на 4 → 4,5. Статистика: 14 → 3,5. Английский: 19 → 4,75. Право: 13 → 3,25. При пороге 4 подходят Python и Английский.'),
dict(n=9, pts=1.5, title='Общее время лекций', topics='цикл, // и %',
 text='В одной строке длительности лекций в минутах, через пробел.\n\nНапечатайте через пробел общее время: сколько получилось целых часов и сколько осталось минут.',
 fin='Одна строка — минуты через пробел.', fout='Два числа через пробел: часы и минуты.',
 pre='',
 inputs=[['80 80 80'],['59'],['60 61'],['90 90 90 90'],['45 15']],
 sol="lectures = input().split()\n\ntotal = 0\nfor lecture in lectures:\n    total += int(lecture)\n\nprint(total // 60, total % 60)\n",
 hint='Сложите минуты в цикле (счётчик до цикла), потом часы — `// 60`, остаток минут — `% 60`.',
 idea='Сначала считаем общую сумму минут, потом переводим её в часы и минуты.',
 steps=['`lectures` — список **строк**, каждую берём как `int(lecture)`.','`total = 0` до цикла, в цикле `total += ...`.','`total // 60` — целые часы, `total % 60` — остаток минут.','Печатаем после цикла через запятую.'],
 mist=['Обнулили `total` внутри цикла: останется только последняя лекция.','Забыли `int`: строки склеятся, а не сложатся.','Поставили `/` вместо `//`: часы получатся дробными.'],
 trace='Лекции `80 80 80`: сумма 240 минут, 240 // 60 = 4 часа, 240 % 60 = 0 минут. Печатаем `4 0`.'),
dict(n=10, pts=1.5, title='Заказы товаров', topics='while True, словарь-накопитель, sorted',
 text='Вводятся строки вида `товар,количество` (количество — целое **положительное**), пока не будет введено слово `END`. Один товар может встретиться несколько раз.\n\nНапечатайте в алфавитном порядке товары, у которых **суммарное** количество **не меньше 100**, каждый с новой строки в виде `товар количество`. Если таких нет, ничего не печатайте.',
 fin='Строки `товар,количество`, последняя строка — `END`.', fout='Строки `товар количество` или пустой вывод.',
 pre='',
 inputs=[['чай,60','кофе,20','чай,50','сахар,100','END'],['мёд,7','END'],['б,100','а,99','а,1','END'],['Х,100','У,50','У,40','END'],['бумага,70','ручка,30','бумага,30','END']],
 sol="totals = {}\n\nwhile True:\n    line = input()\n    if line == 'END':\n        break\n    item, count = line.split(',')\n    if item in totals:\n        totals[item] += int(count)\n    else:\n        totals[item] = int(count)\n\nfor item in sorted(totals):\n    if totals[item] >= 100:\n        print(item, totals[item])\n",
 hint='Сначала накопите суммы в словаре. Потом переберите `sorted(totals)` (ключи по алфавиту) и печатайте те, у кого сумма `>= 100`.',
 idea='Сначала словарь «товар → сумма», затем проход по ключам в алфавитном порядке с фильтром.',
 steps=['`totals = {}` — до цикла.','Если товар уже есть, прибавляем `totals[item] += int(count)`, иначе создаём запись.','`sorted(totals)` — ключи по алфавиту.','`totals[item] >= 100` — «не меньше», включая ровно 100.','`print(item, totals[item])` — через пробел.'],
 mist=['`>` вместо `>=`: товар ровно на 100 пропадёт.','Забыли `sorted`: порядок будет порядком добавления.','Забыли `int(count)`: строки склеиваются (`"60" + "50"`).'],
 trace='Чай: 60 + 50 = 110, кофе: 20, сахар: 100. По алфавиту: кофе (20, не подходит), сахар (100, подходит), чай (110, подходит). Печатаем `сахар 100` и `чай 110`.'),
]
